fs.writeFileSync(path.join(MOD,'cultural_exchange.mod'),'version="1.0.0"\ntags={\n\t"Gameplay"\n\t"Culture"\n\t"Decisions"\n\t"Game Rules"\n}\nname="Cultural Exchange - Adopt Foreign Styles and Buy Innovations"\nsupported_version="1.20.*"\npicture="thumbnail.png"\npath="mod/cultural_exchange"\n');
